+    graph.nodes.insert(branch_b.id.clone(), branch_b);
+    graph.nodes.insert(fan_in.id.clone(), fan_in);
+    graph.edges.push(Edge::new("start", "seed"));
+    graph.edges.push(Edge::new("seed", "fork"));
